import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import catalog from "../generated/catalog.json" with { type: "json" };
import highlightFile from "../generated/highlight.json" with { type: "json" };
import snippetFile from "../generated/snippets.json" with { type: "json" };

// The catalog is generated by `npm run generate:catalog` from the Rust story
// registry, and the invariants about each component — that its type exists,
// that its snippet constructs it, that its events match the source — are Rust
// tests in crates/gallery/src/story.rs. What is left to check here is that the
// committed file still describes the stories the gallery actually ships, which
// catches a stale export without needing a cargo build.
const { components, categories } = catalog;
const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

test("the generated catalog lists every stable Rust story exactly once, in order", async () => {
  const storySource = await readFile(
    path.join(repositoryRoot, "crates/gallery/src/story.rs"),
    "utf8",
  );

  const order = storySource
    .slice(storySource.indexOf("pub const ALL:"))
    .split("];")[0]
    .matchAll(/Self::(\w+),/g);
  const variants = [...order].map((match) => match[1]);

  const slugForVariant = new Map(
    [...storySource.matchAll(/Self::(\w+) => "([a-z0-9-]+)"/g)].map((match) => [
      match[1],
      match[2],
    ]),
  );
  const expected = variants.map((variant) => slugForVariant.get(variant));

  assert.deepEqual(
    components.map(({ slug }) => slug),
    expected,
    "site/generated/catalog.json is stale — run npm run generate:catalog",
  );
});

test("every catalog entry carries what the site renders", async () => {
  const seen = new Set();
  for (const component of components) {
    assert.equal(Number.isInteger(component.sequence), true, `${component.slug} has no sequence`);
    assert.ok(!seen.has(component.slug), `${component.slug} appears twice`);
    seen.add(component.slug);

    assert.match(component.title, /\S/);
    assert.match(component.compactLabel, /\S/);
    assert.match(component.summary, /\S.*\S/);
    assert.match(component.category, /\S/);
    assert.ok(categories.includes(component.category), `${component.category} is not grouped`);
    // A measured height, not a two-value guess: a frame sized from anything
    // else leaves dead space or clips the demo.
    assert.equal(Number.isInteger(component.height), true, `${component.slug} has no height`);
    assert.ok(
      component.height >= 40 && component.height <= 2000,
      `${component.slug} reports an implausible height of ${component.height}`,
    );
    assert.match(component.source, /^crates\/gpui-ai\/src\/[a-z_]+\.rs$/);
    assert.match(component.usage, new RegExp(`${component.api}::new`));
    assert.match(component.windowTitle, /gpui-ai$/);
    assert.match(component.limitation, /\S.*\S/);

    for (const key of ["ownership", "interaction", "semantics", "overflow"]) {
      assert.match(component.behavior[key], /\S.*\S/, `${component.slug} has no ${key} note`);
    }

    assert.ok(Array.isArray(component.events));
    assert.equal(component.event, component.events[0] ?? null);
    assert.equal(
      /typed .*Event contracts? and stable application IDs/.test(component.behavior.interaction),
      component.events.length > 0,
      component.slug,
    );

    for (const variant of component.variants) {
      assert.match(variant.id, /^[a-z0-9][a-z0-9-]*$/);
      assert.match(variant.label, /\S/);
    }
  }
});

test("every component page has a snippet cut from the gallery's own source", () => {
  const { snippets } = snippetFile;

  for (const component of components) {
    const forStory = snippets[component.slug];
    assert.ok(forStory, `${component.slug} has no snippet — add a // snippet:start marker`);

    const variants = Object.keys(forStory);
    assert.ok(variants.length > 0, `${component.slug} has an empty snippet set`);

    for (const [variant, code] of Object.entries(forStory)) {
      assert.match(code, /\S/, `${component.slug}/${variant} is empty`);
      assert.doesNotMatch(code, /snippet:(start|end)/, "markers must not leak into the snippet");
      assert.doesNotMatch(code, /^\s*\|\|/, `${component.slug}/${variant} kept its closure syntax`);
      assert.equal(code, code.trimEnd(), "snippets are trimmed");
      // A snippet is only useful if it shows the component it documents.
      if (variant === "default") {
        assert.ok(
          code.includes(component.api),
          `${component.slug}'s snippet never mentions ${component.api}`,
        );
      }
      // A snippet that is one `let x = Type::new(...)` is a page with a
      // constructor on it and nothing else. Nine stories published exactly
      // that, because their components are entities and everything that makes
      // them worth using — columns, items, the states they answer with —
      // happens on the lines after the region ended.
      const lines = code.split(String.fromCharCode(10)).filter((line) => line.trim().length > 0);
      const bareConstructor = /^\s*let (mut )?[a-z_]+ = [A-Za-z]+::new\(.*\);?$/;
      assert.ok(
        !(lines.length === 1 && bareConstructor.test(lines[0])),
        `${component.slug}/${variant} publishes only a constructor: ${lines[0]}`,
      );

      // Named variants must be states the story actually offers.
      if (variant !== "default") {
        assert.ok(
          component.variants.some(({ id }) => id === variant),
          `${component.slug} has a snippet for unknown variant ${variant}`,
        );
      }
    }
  }

  assert.equal(
    Object.keys(snippets).length,
    components.length,
    "snippets.json should cover exactly the catalog",
  );
});

test("every component's type resolves to a rustdoc page the site can link", async () => {
  // S-16 derives `/api/gpui_ai/<module>/struct.<Api>.html` from the catalog.
  // Rustdoc lays items out by module and names each file after the item's
  // kind, so both assumptions have to hold or 34 pages get a dead link.
  for (const component of components) {
    const module = path.basename(component.source, ".rs");
    const source = await readFile(path.join(repositoryRoot, component.source), "utf8");

    assert.match(
      component.source,
      new RegExp(`/${module}\\.rs$`),
      `${component.slug}'s source is not a crate module`,
    );
    assert.ok(
      source.includes(`pub struct ${component.api}`),
      `${component.api} is not a pub struct in ${component.source}, so struct.*.html is wrong`,
    );
  }
});

test("every highlighted snippet is still, exactly, the snippet", () => {
  const { snippets } = snippetFile;
  const highlighted = highlightFile.snippets;

  // Highlighting is a build step over generated data, and the way it goes
  // wrong is silently: a token dropped, a newline eaten, an escape decoded
  // twice. The page shows these tokens, so what they reassemble into is what a
  // reader reads and copies out by hand.
  assert.deepEqual(
    Object.keys(highlighted).sort(),
    Object.keys(snippets).sort(),
    "highlight.json and snippets.json describe different components",
  );

  let tokens = 0;
  for (const [slug, variants] of Object.entries(snippets)) {
    assert.deepEqual(
      Object.keys(highlighted[slug]).sort(),
      Object.keys(variants).sort(),
      `${slug} has different variants in the two files`,
    );

    for (const [variant, code] of Object.entries(variants)) {
      const lines = highlighted[slug][variant];
      const recovered = lines.map((line) => line.map(([text]) => text).join("")).join("\n");
      assert.equal(recovered, code, `${slug}/${variant} does not reassemble`);
      tokens += lines.reduce((total, line) => total + line.length, 0);
    }
  }

  // A file of one plain token per line would reassemble perfectly and be no
  // highlighting at all.
  assert.ok(tokens > 1000, `only ${tokens} tokens across every snippet`);
});

test("every token category the data uses is one the themes can paint", () => {
  const declared = Object.entries(highlightFile.categories);
  assert.ok(declared.length >= 4, "too few categories to be highlighting anything");

  const used = new Set();
  for (const variants of Object.values(highlightFile.snippets)) {
    for (const lines of Object.values(variants)) {
      for (const line of lines) {
        for (const [, category] of line) if (category) used.add(category);
      }
    }
  }

  // A category with no token is dead weight in the stylesheet; a token with no
  // category is a colour nothing declares.
  assert.deepEqual(
    [...used].sort(),
    declared.map(([name]) => name).sort(),
    "the categories the data uses and the ones it declares disagree",
  );
  for (const [name, token] of declared) {
    assert.match(token, /^--ai-[a-z-]+$/, `${name} is painted from ${token}, which is not a theme token`);
  }
});

test("the stories with a switcher report their variants", () => {
  const bySlug = (slug) => components.find((component) => component.slug === slug);

  assert.deepEqual(
    bySlug("chat").variants.map(({ id }) => id),
    ["conversation", "welcome"],
  );
  for (const slug of ["records-table", "diff-table", "filter-table", "comparison-table"]) {
    assert.ok(bySlug(slug).variants.length > 1, `${slug} should offer table states`);
  }
  assert.deepEqual(bySlug("loading").variants, []);
});
